sys_script.script:
(function syncRefundDecisionToCase(current, previous) {
    if (current.getValue('decision') === previous.getValue('decision')) {
        return;
    }

    // Copy-down: auto-approved refunds approve the full requested amount.
    if (current.getValue('decision') === 'auto_approved' && !current.getValue('amount_approved')) {
        current.setValue('amount_approved', current.getValue('amount_requested'));
        current.update();
    }

    var caseGr = new GlideRecord('sn_customerservice_case');
    if (!caseGr.get(current.getValue('case'))) {
        return;
    }

    var decision = current.getValue('decision');
    var requestType = current.getValue('request_type');

    if (decision === 'auto_escalated') {
        caseGr.setValue('x_2145749_qc_fraud_review_required', true);
        caseGr.setValue('x_2145749_qc_needs_manual_review', true);
        caseGr.setValue('x_2145749_qc_resolution_type', 'pending');
        caseGr.work_notes = 'Refund request ' + current.getValue('number') +
            ' escalated by the Automated Resolution Engine: ' + current.getValue('decision_notes');

    } else if (decision === 'auto_approved') {
        caseGr.setValue('x_2145749_qc_auto_resolved', true);
        caseGr.setValue('x_2145749_qc_needs_manual_review', false);
        caseGr.setValue('x_2145749_qc_fraud_review_required', false);
        caseGr.setValue('x_2145749_qc_resolution_type', requestType === 'reorder' ? 'reorder' : 'refund');
        caseGr.work_notes = 'Refund request ' + current.getValue('number') +
            ' auto-approved by the Automated Resolution Engine.';

    } else if (decision === 'manually_approved') {
        caseGr.setValue('x_2145749_qc_auto_resolved', false);
        caseGr.setValue('x_2145749_qc_fraud_review_required', false);
        caseGr.setValue('x_2145749_qc_needs_manual_review', false);
        caseGr.setValue('x_2145749_qc_resolution_type', requestType === 'reorder' ? 'reorder' : 'refund');
        caseGr.work_notes = 'Refund request ' + current.getValue('number') +
            ' manually approved by ' + gs.getUserDisplayName() +
            '. Amount approved: ' + current.getValue('amount_approved');

    } else if (decision === 'manually_denied') {
        caseGr.setValue('x_2145749_qc_auto_resolved', false);
        caseGr.setValue('x_2145749_qc_fraud_review_required', false);
        caseGr.setValue('x_2145749_qc_needs_manual_review', false);
        caseGr.setValue('x_2145749_qc_resolution_type', 'no_action');
        caseGr.work_notes = 'Refund request ' + current.getValue('number') +
            ' manually denied by ' + gs.getUserDisplayName() +
            '. Reason: ' + current.getValue('decision_notes');
    }

    caseGr.update();
})(current, previous);
